If(ThisItem.ID = Max(Filter(colTulas,RelatedRowID=varSelectedPlanilla.ID),ID),

ForAll(
    'gal Tulas'.AllItems As Gal,
    UpdateIf(
        colTulas,
        Value(Last(Split(Gal.Label1.Text,"-")).Value) = ID && RelatedRowID=varSelectedPlanilla.ID,
        {
            Numero: Trim(Gal.TextInput1.Text)
            ,RelatedRowID: varSelectedPlanilla.ID
        }
    )
);

Collect(
    colTulas,
    {
        Numero: "",
        RelatedRowID: varSelectedPlanilla.ID,
        ID: Max(
            Filter(
                colTulas,
                RelatedRowID = varSelectedPlanilla.ID
            ),
            ID
        ) + 1
    }
),

ForAll(
    'gal Tulas'.AllItems As Gal,
    UpdateIf(
        colTulas,
        Value(Last(Split(Gal.Label1.Text,"-")).Value) = ID && RelatedRowID=varSelectedPlanilla.ID,
        {
            Numero: Trim(Gal.TextInput1.Text)
            ,RelatedRowID: varSelectedPlanilla.ID
        }
    )
);


UpdateContext({varThisRowID: ThisItem.ID});

RemoveIf(colTulas,ID = varThisRowID && RelatedRowID=varSelectedPlanilla.ID);

UpdateIf(colTulas, ID > varThisRowID, {ID: ID-1});

)
